quickstart.claude:
const Anthropic = require('@anthropic-ai/sdk');
const pkg = require('./agent-package.json');
const client = new Anthropic();

const PCC_BASE = pkg.api_base; // https://capability.network
const tools = pkg.tools.map(t => ({ name: t.name, description: t.description, input_schema: t.input_schema }));

let apiKey = null;

async function callTool(tool, input) {
  let path = tool.endpoint.path;
  // Replace path params like {jobId} with actual values
  for (const [k, v] of Object.entries(input)) {
    path = path.replace(`{${k}}`, v);
  }
  const url = `${PCC_BASE}${path}`;
  const headers = { 'Content-Type': 'application/json' };
  if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;
  const res = await fetch(url, {
    method: tool.endpoint.method,
    headers,
    body: tool.endpoint.method !== 'GET' ? JSON.stringify(input) : undefined,
  });
  const data = await res.json();
  // Cache API key from provision_api_key response
  if (tool.name === 'provision_api_key' && data.api_key) apiKey = data.api_key;
  return data;
}

async function chat(userMessage) {
  const messages = [{ role: 'user', content: userMessage }];
  while (true) {
    const response = await client.messages.create({
      model: 'claude-sonnet-4-20250514',
      max_tokens: 4096,
      system: pkg.system_prompt,
      tools,
      messages,
    });
    messages.push({ role: 'assistant', content: response.content });
    if (response.stop_reason !== 'tool_use') break;
    const results = [];
    for (const block of response.content) {
      if (block.type !== 'tool_use') continue;
      const tool = pkg.tools.find(t => t.name === block.name);
      const result = await callTool(tool, block.input);
      results.push({ type: 'tool_result', tool_use_id: block.id, content: JSON.stringify(result) });
    }
    messages.push({ role: 'user', content: results });
  }
  return messages;
}

chat('I want to register my HPLC lab and start accepting jobs on the PCC network.');

quickstart.openai:
const OpenAI = require('openai');
const pkg = require('./agent-package.json');
const client = new OpenAI();

const PCC_BASE = pkg.api_base; // https://capability.network
const tools = pkg.tools.map(t => ({
  type: 'function',
  function: { name: t.name, description: t.description, parameters: t.input_schema },
}));

let apiKey = null;

async function callTool(toolName, input) {
  const tool = pkg.tools.find(t => t.name === toolName);
  let path = tool.endpoint.path;
  for (const [k, v] of Object.entries(input)) path = path.replace(`{${k}}`, v);
  const headers = { 'Content-Type': 'application/json' };
  if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;
  const res = await fetch(`${PCC_BASE}${path}`, {
    method: tool.endpoint.method,
    headers,
    body: tool.endpoint.method !== 'GET' ? JSON.stringify(input) : undefined,
  });
  const data = await res.json();
  if (toolName === 'provision_api_key' && data.api_key) apiKey = data.api_key;
  return data;
}

async function chat(userMessage) {
  const messages = [
    { role: 'system', content: pkg.system_prompt },
    { role: 'user', content: userMessage },
  ];
  while (true) {
    const response = await client.chat.completions.create({ model: 'gpt-4o', tools, messages });
    const msg = response.choices[0].message;
    messages.push(msg);
    if (!msg.tool_calls) break;
    for (const call of msg.tool_calls) {
      const result = await callTool(call.function.name, JSON.parse(call.function.arguments));
      messages.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(result) });
    }
  }
  return messages;
}

chat('I want to register my HPLC lab and start accepting jobs on the PCC network.');
